package paylink

import (
	"sort"
	"strings"
)

// domainToASCII is the URL Standard's "domain to ASCII" with beStrict false: UTS #46 ToASCII
// with CheckHyphens, UseSTD3ASCIIRules and VerifyDnsLength off, CheckBidi and CheckJoiners on,
// non-transitional. This is what turns "sandаls.com" (a Cyrillic а) into "xn--sandls-6nf.com",
// which is why the stored link cannot pass for sandals.com.
//
// An ASCII host is handled exactly: lower-cased, and every xn-- label decoded and checked.
//
// A non-ASCII code point is mapped through idna_table.go, which was generated by asking
// Deno's own new URL() about every code point (the generator is in that file). The table
// holds only code points whose answer does not depend on their neighbours. Without Unicode
// normalization and bidi data (not in Go's standard library; golang.org/x/net/idna has them
// but needs a library review first, docs/GO-MIGRATION.md ruling 15), the rest cannot be
// mapped faithfully, so a host using one of them is REFUSED here ("That doesn't look like a
// link") where Deno may have accepted it:
//   - right-to-left letters and digits (Hebrew, Arabic, ...), which the bidi rule judges by
//     their neighbours;
//   - combining marks, and anything that maps to one first, which normalization may fuse
//     with the letter before;
//   - Hangul conjoining jamo, which compose with each other;
//   - zero-width joiners, judged by their neighbours;
//   - characters that map to a full stop plus more (U+2488 "⒈"); the three ideographic full
//     stops (U+3002, U+FF0E, U+FF61) are mapped exactly.
//
// Refusing is the safe direction for a pay link, and every host Deno refused is refused too.
func domainToASCII(domain string) (string, bool) {
	var mapped strings.Builder
	for _, r := range domain {
		switch {
		case r < 0x80:
			mapped.WriteRune(asciiLower(r))
		case r == 0x3002 || r == 0xff0e || r == 0xff61:
			mapped.WriteByte('.')
		default:
			m, ok := idnaMap(r)
			if !ok {
				return "", false
			}
			mapped.WriteString(m)
		}
	}
	// Normalization to NFC would come here; the table only admits code points for which it
	// changes nothing.

	labels := strings.Split(mapped.String(), ".")
	for i, label := range labels {
		if strings.HasPrefix(label, "xn--") {
			if !isASCII(label) || !validPunycodeLabel(label[4:]) {
				return "", false
			}
			continue
		}
		if isASCII(label) {
			continue
		}
		// Validity criterion 4 (CheckHyphens off): a label must not begin with "xn--"; this
		// one does not, or it would have gone the branch above.
		encoded, ok := punycodeEncode([]rune(label))
		if !ok {
			return "", false
		}
		labels[i] = "xn--" + encoded
	}
	result := strings.Join(labels, ".")
	if result == "" {
		return "", false
	}
	return result, true
}

// validPunycodeLabel decodes an xn-- label and applies UTS #46's checks to what comes out: it
// must decode, must not be empty or all ASCII, must not itself begin with "xn--", and every
// code point must be one UTS #46 calls valid, which here means the table maps it to itself.
func validPunycodeLabel(encoded string) bool {
	decoded, ok := punycodeDecode(encoded)
	if !ok || len(decoded) == 0 {
		return false
	}
	nonASCII := false
	for _, r := range decoded {
		if r < 0x80 {
			continue
		}
		nonASCII = true
		m, ok := idnaMap(r)
		if !ok || m != string(r) {
			return false
		}
	}
	if !nonASCII {
		return false
	}
	return !strings.HasPrefix(string(decoded), "xn--")
}

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

// The kinds of run in idnaRuns.
const (
	idnaShift  = iota // every code point maps to itself plus d (d is 0 for a valid one)
	idnaPairs         // upper/lower pairs: an even offset from lo maps to the next code point
	idnaString        // every code point maps to idnaStrings[d] ("" when it is ignored)
)

type idnaRun struct {
	lo, hi rune
	kind   uint8
	d      int32
}

// idnaMap is UTS #46's mapping for one non-ASCII code point, false when the table does not
// hold it (refused by Deno, or judged by its neighbours; see domainToASCII).
func idnaMap(r rune) (string, bool) {
	i := sort.Search(len(idnaRuns), func(i int) bool { return idnaRuns[i].hi >= r })
	if i == len(idnaRuns) || idnaRuns[i].lo > r {
		return "", false
	}
	run := idnaRuns[i]
	switch run.kind {
	case idnaShift:
		return string(r + run.d), true
	case idnaPairs:
		if (r-run.lo)%2 == 0 {
			return string(r + 1), true
		}
		return string(r), true
	default:
		return idnaStrings[run.d], true
	}
}

// Punycode, RFC 3492.
const (
	pcBase        = 36
	pcTMin        = 1
	pcTMax        = 26
	pcSkew        = 38
	pcDamp        = 700
	pcInitialBias = 72
	pcInitialN    = 128
	pcMaxInt      = 1<<31 - 1
)

func pcAdapt(delta, numPoints int, first bool) int {
	if first {
		delta /= pcDamp
	} else {
		delta /= 2
	}
	delta += delta / numPoints
	k := 0
	for delta > ((pcBase-pcTMin)*pcTMax)/2 {
		delta /= pcBase - pcTMin
		k += pcBase
	}
	return k + (pcBase-pcTMin+1)*delta/(delta+pcSkew)
}

func pcThreshold(k, bias int) int {
	switch {
	case k <= bias:
		return pcTMin
	case k >= bias+pcTMax:
		return pcTMax
	}
	return k - bias
}

func pcEncodeDigit(d int) byte {
	if d < 26 {
		return byte('a' + d)
	}
	return byte('0' + d - 26)
}

func pcDecodeDigit(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c-'0') + 26
	case c >= 'A' && c <= 'Z':
		return int(c - 'A')
	case c >= 'a' && c <= 'z':
		return int(c - 'a')
	}
	return pcBase
}

func punycodeEncode(input []rune) (string, bool) {
	var out []byte
	for _, r := range input {
		if r < 0x80 {
			out = append(out, byte(r))
		}
	}
	b := len(out)
	h := b
	if b > 0 {
		out = append(out, '-')
	}
	n, delta, bias := pcInitialN, 0, pcInitialBias
	for h < len(input) {
		m := pcMaxInt
		for _, r := range input {
			if int(r) >= n && int(r) < m {
				m = int(r)
			}
		}
		if m-n > (pcMaxInt-delta)/(h+1) {
			return "", false
		}
		delta += (m - n) * (h + 1)
		n = m
		for _, r := range input {
			if int(r) < n {
				delta++
				if delta > pcMaxInt {
					return "", false
				}
			}
			if int(r) == n {
				q := delta
				for k := pcBase; ; k += pcBase {
					t := pcThreshold(k, bias)
					if q < t {
						break
					}
					out = append(out, pcEncodeDigit(t+(q-t)%(pcBase-t)))
					q = (q - t) / (pcBase - t)
				}
				out = append(out, pcEncodeDigit(q))
				bias = pcAdapt(delta, h+1, h == b)
				delta = 0
				h++
			}
		}
		delta++
		n++
	}
	return string(out), true
}

func punycodeDecode(input string) ([]rune, bool) {
	var out []rune
	in := 0
	if b := strings.LastIndexByte(input, '-'); b > 0 {
		for j := 0; j < b; j++ {
			if input[j] >= 0x80 {
				return nil, false
			}
			out = append(out, rune(input[j]))
		}
		in = b + 1
	}
	n, i, bias := pcInitialN, 0, pcInitialBias
	for in < len(input) {
		oldi, w := i, 1
		for k := pcBase; ; k += pcBase {
			if in >= len(input) {
				return nil, false
			}
			digit := pcDecodeDigit(input[in])
			in++
			if digit >= pcBase || digit > (pcMaxInt-i)/w {
				return nil, false
			}
			i += digit * w
			t := pcThreshold(k, bias)
			if digit < t {
				break
			}
			if w > pcMaxInt/(pcBase-t) {
				return nil, false
			}
			w *= pcBase - t
		}
		bias = pcAdapt(i-oldi, len(out)+1, oldi == 0)
		if i/(len(out)+1) > pcMaxInt-n {
			return nil, false
		}
		n += i / (len(out) + 1)
		i %= len(out) + 1
		if n > 0x10ffff || (n >= 0xd800 && n <= 0xdfff) {
			return nil, false
		}
		out = append(out, 0)
		copy(out[i+1:], out[i:])
		out[i] = rune(n)
		i++
	}
	return out, true
}
